/**
 * Permission types.
 *
 * Wire-level types (PermissionMode, PermissionUpdate, etc) come from
 * `../protocol/`. This file adds SDK-local types — the `CanUseTool`
 * callback shape — which never crosses the JSONL boundary.
 */
export type { PermissionBehavior, PermissionDecisionClassification, PermissionUpdateDestination, PermissionRuleValue, } from '../protocol/index.js';
import type { PermissionBehavior, PermissionDecisionClassification, PermissionUpdateDestination, PermissionRuleValue } from '../protocol/index.js';
/**
 * Permission mode for controlling how tool executions are handled.
 */
export type PermissionMode = 'default' | 'acceptEdits' | 'bypassPermissions' | 'yolo' | 'plan' | 'dontAsk' | 'auto';
export type PermissionUpdate = {
    type: 'addRules';
    rules: PermissionRuleValue[];
    behavior: PermissionBehavior;
    destination: PermissionUpdateDestination;
} | {
    type: 'replaceRules';
    rules: PermissionRuleValue[];
    behavior: PermissionBehavior;
    destination: PermissionUpdateDestination;
} | {
    type: 'removeRules';
    rules: PermissionRuleValue[];
    behavior: PermissionBehavior;
    destination: PermissionUpdateDestination;
} | {
    type: 'setMode';
    mode: PermissionMode;
    destination: PermissionUpdateDestination;
} | {
    type: 'addDirectories';
    directories: string[];
    destination: PermissionUpdateDestination;
} | {
    type: 'removeDirectories';
    directories: string[];
    destination: PermissionUpdateDestination;
};
export type PermissionDecisionReasonType = 'rule' | 'mode' | 'subcommandResults' | 'permissionPromptTool' | 'hook' | 'asyncAgent' | 'sandboxOverride' | 'workingDir' | 'safetyCheck' | 'classifier' | 'other';
export type PermissionResult = {
    behavior: 'allow';
    updatedInput?: Record<string, unknown>;
    updatedPermissions?: PermissionUpdate[];
    toolUseID?: string;
    decisionClassification?: PermissionDecisionClassification;
} | {
    behavior: 'deny';
    message: string;
    interrupt?: boolean;
    toolUseID?: string;
    decisionClassification?: PermissionDecisionClassification;
};
/**
 * ExitPlanMode-specific approval context.
 *
 * qodercli stores the plan body on disk and the tool's input is empty —
 * the planPath/planContent fields surface the runtime plan so approval UIs
 * can render it inline without re-reading from disk.
 */
export type ExitPlanModeApprovalDetails = {
    planPath?: string;
    planContent?: string;
};
export type CanUseToolOptions = {
    signal: AbortSignal;
    suggestions?: PermissionUpdate[];
    blockedPath?: string;
    decisionReason?: string;
    decisionReasonType?: PermissionDecisionReasonType;
    classifierApprovable?: boolean;
    title?: string;
    displayName?: string;
    description?: string;
    toolUseID: string;
    agentID?: string;
    /** Tool-specific runtime context (e.g. ExitPlanMode plan body). */
    exitPlanMode?: ExitPlanModeApprovalDetails;
};
export type CanUseTool = (toolName: string, input: Record<string, unknown>, options: CanUseToolOptions) => Promise<PermissionResult>;